def transform(grid):
    """Restore 6-covered cells in a diagonally symmetric color matrix."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    # The unmasked half gives the exact value of each covered cell by transpose.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6 and c < h and r < w and grid[c][r] != 6:
                out[r][c] = grid[c][r]

    # If a mask covers both symmetric cells (or a diagonal cell), infer from
    # the surrounding completed pattern, maintaining transpose symmetry.
    unresolved = {(r, c) for r in range(h) for c in range(w) if out[r][c] == 6}
    while unresolved:
        updates = []
        for r, c in sorted(unresolved):
            if (c, r) not in unresolved and (r, c) > (c, r):
                continue
            vals = []
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    if (rr, cc) != (r, c) and out[rr][cc] != 6:
                        vals.append(out[rr][cc])
            if vals:
                counts = Counter(vals)
                color = max(counts, key=lambda x: (counts[x], x))
                updates.append((r, c, color))
        if not updates:
